INSERT INTO subscriptions (family_id,member_id,plan_id,period_start,period_end,amount,amount_paid,payment_date,receipt_number,payment_method,status,collected_by) SELECT id,(id-1)*2+1,1,'2026-07-01','2026-07-31',100,CASE WHEN id%5=0 THEN 50 ELSE 100 END,'2026-07-'||printf('%02d',(id%27)+1),'RCP-DEMO-'||printf('%03d',id),CASE WHEN id%3=0 THEN 'UPI' ELSE 'Cash' END,CASE WHEN id%5=0 THEN 'Partial' ELSE 'Paid' END,1 FROM families;
INSERT INTO donations (donor_name,donor_phone,donor_address,family_id,category_id,amount,donation_date,receipt_number,purpose,payment_method,received_by,remarks) SELECT m.name,m.mobile,'Kozhikode',m.family_id,(m.family_id%5)+1,2500+m.family_id*250,'2026-'||printf('%02d',(m.family_id%8)+1)||'-'||printf('%02d',(m.family_id%25)+1),'DON-DEMO-'||printf('%03d',m.family_id),'Mahallu support',CASE WHEN m.family_id%3=0 THEN 'UPI' ELSE 'Cash' END,1,'Demo donation' FROM members m WHERE m.relationship='Head';
INSERT INTO transactions (txn_date,account_id,type,amount,payment_method,reference,description,linked_module,linked_id,receipt_number,transaction_ref,created_by) SELECT '2026-'||printf('%02d',(f.id%8)+1)||'-'||printf('%02d',(f.id%25)+1),(SELECT id FROM ledger_accounts WHERE code='INC-SUB'),'Income',3000+f.id*100,'UPI','INC-'||printf('%03d',f.id),'Collection income','subscription',f.id,'TXN-IN-'||printf('%03d',f.id),'REF-IN-'||printf('%03d',f.id),1 FROM families f;
INSERT INTO transactions (txn_date,account_id,type,amount,payment_method,reference,description,linked_module,linked_id,receipt_number,transaction_ref,created_by) SELECT '2026-'||printf('%02d',(f.id%8)+1)||'-'||printf('%02d',(f.id%25)+1),(SELECT id FROM ledger_accounts WHERE code='EXP-MAINT'),'Expense',1000+f.id*50,'Cash','EXP-'||printf('%03d',f.id),'Maintenance expense','accounting',0,'TXN-EX-'||printf('%03d',f.id),'REF-EX-'||printf('%03d',f.id),1 FROM families f;
